def before_save(self):
	if not self.on_hold:
		self.release_date = ""
	elif self.on_hold and not self.hold_type:
		self.hold_type = "All"

def is_blocked_for(self, hold_type: str) -> bool:
	"""Whether transactions of `hold_type` ("Invoices", "Payments" or "All") are on hold today."""
	return bool(
		self.on_hold
		and self.hold_type in ("All", hold_type)
		and (not self.release_date or getdate(nowdate()) < getdate(self.release_date))
	)

def load_dashboard_info(self):
	info = get_dashboard_info(self.doctype, self.name)
	self.set_onload("dashboard_info", info)

def autoname(self):
	supp_master_name = frappe.defaults.get_global_default("supp_master_name")
	if supp_master_name == "Supplier Name":
		self.name = self.supplier_name
	elif supp_master_name == "Naming Series":
		set_name_by_naming_series(self)
	else:
		set_name_from_naming_options(frappe.get_meta(self.doctype).autoname, self)

def add_role_for_user(self):
	for portal_user in self.portal_users:
		add_role_for_portal_user(portal_user, "Supplier")

def _add_supplier_role(self, portal_user):
	if not portal_user.is_new():
		return

	user_doc = frappe.get_doc("User", portal_user.user)
	roles = {r.role for r in user_doc.roles}

	if "Supplier" in roles:
		return

	if "System Manager" not in frappe.get_roles():
		frappe.msgprint(
			_("Please add 'Supplier' role to user {0}.").format(portal_user.user),
			alert=True,
		)
		return

	user_doc.add_roles("Supplier")
	frappe.msgprint(_("Added Supplier Role to User {0}.").format(frappe.bold(user_doc.name)), alert=True)

def validate_primary_contact_and_address(self):
	for fieldname, link_doctype in (
		("supplier_primary_contact", "Contact"),
		("supplier_primary_address", "Address"),
	):
		name = self.get(fieldname)
		if not name or not self.has_value_changed(fieldname):
			continue

		if not frappe.db.exists(
			"Dynamic Link",
			{
				"parenttype": link_doctype,
				"parent": name,
				"link_doctype": "Supplier",
				"link_name": self.name,
			},
		):
			frappe.throw(
				_("{0} {1} is not linked to Supplier {2}").format(
					_(link_doctype), frappe.bold(name), frappe.bold(self.name)
				)
			)

def get_supplier_group_details(self):
	doc = frappe.get_doc("Supplier Group", self.supplier_group)
	self.payment_terms = ""
	self.accounts = []

	if doc.accounts:
		for account in doc.accounts:
			child = self.append("accounts")
			child.company = account.company
			child.account = account.account

	if doc.payment_terms:
		self.payment_terms = doc.payment_terms

def validate_internal_supplier(self):
	if not self.is_internal_supplier:
		self.represents_company = ""

	if self.disabled:
		return

	internal_supplier = frappe.db.get_value(
		"Supplier",
		{
			"is_internal_supplier": 1,
			"represents_company": self.represents_company,
			"disabled": 0,
			"name": ("!=", self.name),
		},
		"name",
	)

	if internal_supplier:
		internal_supplier_link = get_link_to_form("Supplier", internal_supplier)
		frappe.throw(
			_(
				"Internal Supplier {0} already exists for {1}. Disable it to make this Supplier internal."
			).format(
				internal_supplier_link,
				frappe.bold(self.represents_company),
			),
			title=_("Internal Supplier Already Exists"),
		)

def create_primary_contact(self):
	from erpnext.selling.doctype.customer.customer import make_contact

	if not self.supplier_primary_contact:
		if self.mobile_no or self.email_id:
			contact = make_contact(self)
			self.db_set("supplier_primary_contact", contact.name)
			self.db_set("mobile_no", self.mobile_no)
			self.db_set("email_id", self.email_id)

def on_trash(self):
	if self.supplier_primary_contact:
		self.db_set("supplier_primary_contact", None)
	if self.supplier_primary_address:
		self.db_set("supplier_primary_address", None)

	delete_contact_and_address("Supplier", self.name)

def before_rename(self, olddn, newdn, merge=False):
	if merge:
		validate_party_currency_before_merging("Supplier", olddn, newdn)

def after_rename(self, olddn, newdn, merge=False):
	if frappe.defaults.get_global_default("supp_master_name") == "Supplier Name":
		self.db_set("supplier_name", newdn)

def _get_invoiced(self):
    precision = self.env['decimal.precision'].precision_get('Product Unit')
    for order in self:
        if order.state != 'purchase':
            order.invoice_status = 'no'
            continue

        if any(
            not float_is_zero(line.qty_to_invoice, precision_digits=precision)
            for line in order.order_line.filtered(lambda l: not l.display_type)
        ):
            order.invoice_status = 'to invoice'
        elif (
            all(
                float_is_zero(line.qty_to_invoice, precision_digits=precision)
                for line in order.order_line.filtered(lambda l: not l.display_type)
            )
            and order.invoice_ids
        ):
            order.invoice_status = 'invoiced'
        else:
            order.invoice_status = 'no'

def _compute_invoice(self):
    for order in self:
        invoices = order.mapped('order_line.invoice_lines.move_id')
        order.invoice_ids = invoices
        order.invoice_count = len(invoices)

def _check_order_line_company_id(self):
    for order in self:
        invalid_companies = order.order_line.product_id.company_id.filtered(
            lambda c: order.company_id not in c._accessible_branches()
        )
        if invalid_companies:
            bad_products = order.order_line.product_id.filtered(
                lambda p: p.company_id and p.company_id in invalid_companies
            )
            raise ValidationError(_(
                "Your RFQ contains products from company %(product_company)s whereas your RFQ belongs to company %(quote_company)s. \n Please change the company of your RFQ or remove the products from other companies (%(bad_products)s).",
                product_company=', '.join(invalid_companies.sudo().mapped('display_name')),
                quote_company=order.company_id.display_name,
                bad_products=', '.join(bad_products.mapped('display_name')),
            ))

def _compute_access_url(self):
    super(PurchaseOrder, self)._compute_access_url()
    for order in self:
        order.access_url = '/my/purchase/%s' % (order.id)

def _compute_bill_matched_ratio(self):
    def get_line_invoiced_ratio(line):
        base_quantity = line.product_qty if line.product_id.purchase_method == 'purchase' else line.qty_received
        return line.qty_invoiced / base_quantity if base_quantity else 0

    for order in self:
        product_lines = order.order_line.filtered(lambda pol: not pol.display_type)
        invoiced_ratio = [get_line_invoiced_ratio(line) for line in product_lines]
        order.bill_matched_ratio = sum(invoiced_ratio) / len(product_lines) * 100 if product_lines else 0

def _compute_date_calendar_start(self):
    for order in self:
        order.date_calendar_start = order.date_approve if (order.state == 'purchase') else order.date_order

def _compute_currency_rate(self):
    for order in self:
        order.currency_rate = self.env['res.currency']._get_conversion_rate(
            from_currency=order.company_id.currency_id,
            to_currency=order.currency_id,
            company=order.company_id,
            date=(order.date_order or fields.Datetime.now()).date(),
        )

def _compute_amount_total_cc(self):
    for order in self:
        order.amount_total_cc = order.amount_total / order.currency_rate

def _compute_date_planned(self):
    """ date_planned = the earliest date_planned across all order lines. """
    for order in self:
        dates_list = order.order_line.filtered(lambda x: not x.display_type and x.date_planned).mapped('date_planned')
        if dates_list:
            order.date_planned = min(dates_list)
        else:
            order.date_planned = False

def _compute_display_name(self):
    for po in self:
        name = po.name
        if po.partner_ref:
            name += ' (' + po.partner_ref + ')'
        if self.env.context.get('show_total_amount') and po.amount_total:
            name += ': ' + formatLang(self.env, po.amount_total, currency_obj=po.currency_id)
        po.display_name = name

def _compute_receipt_status(self):
    for order in self:
        if order.state != 'purchase' or not order.order_line:
            order.receipt_status = False
        elif all(line.qty_received >= line.product_qty for line in order.order_line):
            order.receipt_status = 'full'
        elif any(line.qty_received for line in order.order_line):
            order.receipt_status = 'partial'
        else:
            order.receipt_status = 'pending'

def _compute_receipt_reminder_email(self):
    for order in self:
        order.receipt_reminder_email = order.partner_id.with_company(order.company_id).receipt_reminder_email
        order.reminder_date_before_receipt = order.partner_id.with_company(order.company_id).reminder_date_before_receipt

def _compute_tax_country_id(self):
    for record in self:
        if record.fiscal_position_id.foreign_vat:
            record.tax_country_id = record.fiscal_position_id.country_id
        else:
            record.tax_country_id = record.company_id.account_fiscal_country_id

def _compute_incoterm_id(self):
    for po in self:
        partner_incoterm = po.partner_id.purchase_incoterm_id
        if partner_incoterm:
            po.incoterm_id = partner_incoterm

def _compute_incoterm_location(self):
    for po in self:
        partner_incoterm_location = po.partner_id.purchase_incoterm_location
        if partner_incoterm_location:
            po.incoterm_location = partner_incoterm_location

def _compute_show_comparison(self):
    line_groupby_product = self.env['purchase.order.line']._read_group(
        [('product_id', 'in', self.order_line.product_id.ids), ('state', '=', 'purchase')],
        ['product_id'],
        ['order_id:array_agg']
    )

    order_by_product = {p: set(o_ids) for p, o_ids in line_groupby_product}
    for record in self:
        record.show_comparison = any(set(record.ids) != order_by_product[p] for p in record.order_line.product_id if p in order_by_product)

def _compute_show_receive_button(self):
    for order in self:
        order.show_receive_button = (
            order.state == 'purchase'
            and any(line.qty_received < line.product_qty for line in order.order_line)
            and all(line.qty_received_method == "manual" for line in order.order_line)
        )

def _compute_purchase_warning_text(self):
    if not self.env.user.has_group('purchase.group_warning_purchase'):
        self.purchase_warning_text = ''
        return
    for order in self:
        warnings = OrderedSet()
        if partner_msg := order.partner_id.purchase_warn_msg:
            warnings.add((order.partner_id.name or order.partner_id.display_name) + ' - ' + partner_msg)
        if partner_parent_msg := order.partner_id.parent_id.purchase_warn_msg:
            parent = order.partner_id.parent_id
            warnings.add((parent.name or parent.display_name) + ' - ' + partner_parent_msg)
        for line in order.order_line:
            if product_msg := line.purchase_line_warn_msg:
                warnings.add(line.product_id.display_name + ' - ' + product_msg)
        order.purchase_warning_text = '\n'.join(warnings)

def action_open_business_doc(self):
    self.ensure_one()
    return {
        'name': _("Order"),
        'type': 'ir.actions.act_window',
        'res_model': 'purchase.order',
        'res_id': self.id,
        'views': [(False, 'form')],
    }

def onchange_date_planned(self):
    if self.date_planned:
        self.order_line.filtered(lambda line: not line.display_type).date_planned = self.date_planned

def _search_is_late(self, operator, value):
    if operator not in ["=", "!="]:
        raise ValidationError(self.env._("Unsupported operator"))
    purchase_domain = self._get_domain_is_late(operator, value)
    if operator == "=" and value or operator == "!=" and not value:
        purchase_lines_late = Domain('order_id', 'any', purchase_domain) & Domain.custom(
            to_sql=lambda table: SQL("%s < %s", table.qty_received, table.product_qty),
        )
        return Domain('order_line', 'any', purchase_lines_late)
    else:
        purchase_lines_on_time = Domain('order_id', 'any', purchase_domain) & Domain.custom(
            to_sql=lambda table: SQL("%s >= %s", table.qty_received, table.product_qty),
        )
        return Domain('order_line', 'any', purchase_lines_on_time)

def create(self, vals_list):
    orders = self.browse()
    for vals in vals_list:
        company_id = vals.get('company_id', self.default_get(['company_id'])['company_id'])
        # Ensures default picking type and currency are taken from the right company.
        self_comp = self.with_company(company_id)
        if vals.get('name', _('New')) == _('New'):
            seq_date = None
            if 'date_order' in vals:
                seq_date = fields.Datetime.context_timestamp(self, fields.Datetime.to_datetime(vals['date_order']))
            vals['name'] = self_comp.env['ir.sequence'].next_by_code('purchase.order', sequence_date=seq_date) or '/'
        orders |= super(PurchaseOrder, self_comp).create(vals)
    return orders

def _unlink_if_cancelled(self):
    for order in self:
        if not order.state == 'cancel':
            raise UserError(_('In order to delete a purchase order, you must cancel it first.'))

def copy(self, default=None):
    ctx = dict(self.env.context)
    ctx.pop('default_product_id', None)
    self = self.with_context(ctx)
    new_pos = super().copy(default=default)
    for line in new_pos.order_line:
        if line.product_id:
            line.date_planned = line._get_date_planned(line._get_seller_info())
    return new_pos

def _must_delete_date_planned(self, field_name):
    # To be overridden
    return field_name == 'order_line'

def onchange(self, values, field_names, fields_spec):
    """
    Override onchange to NOT update all date_planned on PO lines when
    date_planned on PO is updated by the change of date_planned on PO lines.
    """
    result = super().onchange(values, field_names, fields_spec)
    if any(self._must_delete_date_planned(field) for field in field_names) and 'value' in result:
        for line in result['value'].get('order_line', []):
            if line[0] == Command.UPDATE and 'date_planned' in line[2]:
                del line[2]['date_planned']
    return result

def _get_report_base_filename(self):
    self.ensure_one()
    return 'Purchase Order-%s' % (self.name)

def onchange_partner_id(self):
    # Ensures all properties and fiscal positions
    # are taken with the company of the order
    # if not defined, with_company doesn't change anything.
    self = self.with_company(self.company_id)
    if not self.partner_id:
        self.fiscal_position_id = False
    else:
        self.fiscal_position_id = self.env['account.fiscal.position']._get_fiscal_position(self.partner_id)
        self.payment_term_id = self.partner_id.property_supplier_payment_term_id.id
        if self.partner_id.buyer_id:
            self.user_id = self.partner_id.buyer_id
    return {}

def _compute_currency_id(self):
    for order in self:
        order = order.with_company(order.company_id)
        if not order.partner_id:
            order.currency_id = order.company_id.currency_id
        else:
            order.currency_id = order.partner_id.property_purchase_currency_id or order.company_id.currency_id

def _compute_document_tax_mode(self):
    for order in self:
        if not order.document_tax_mode:
            company = order.company_id or self.env.company
            order.document_tax_mode = company.account_price_include

def message_post(self, **kwargs):
    if self.env.context.get('mark_rfq_as_sent'):
        self._mark_rfqs_as_sent()
        kwargs['notify_author_mention'] = kwargs.get('notify_author_mention', True)
    return super().message_post(**kwargs)

def _message_mail_after_hook(self, mails):
    self._mark_rfqs_as_sent()
    return super()._message_mail_after_hook(mails)

def _notify_get_recipients_groups(self, message, model_description):
    # Tweak 'view document' button for portal customers, calling directly routes for confirm specific to PO model.
    groups = super()._notify_get_recipients_groups(message, model_description)
    if not self:
        return groups

    self.ensure_one()
    try:
        customer_portal_group = next(group for group in groups if group[0] == 'portal_customer')
    except StopIteration:
        pass
    else:
        access_opt = customer_portal_group[2].setdefault('button_access', {})
        if self.env.context.get('is_reminder'):
            access_opt['title'] = _('View')
        else:
            access_opt.update(
                title=_("View Quotation") if self.state in ('draft', 'sent') else _("View Order"),
                url=self.get_base_url() + self.get_confirm_url(),
            )

    return groups

def _track_log_get_default_subtype(self, track_init_values):
    self.ensure_one()
    if 'state' in track_init_values and self.state == 'purchase':
        if track_init_values['state'] == 'to approve':
            return self.env.ref('purchase.mt_rfq_approved')
        return self.env.ref('purchase.mt_rfq_confirmed')
    elif 'state' in track_init_values and self.state == 'to approve':
        return self.env.ref('purchase.mt_rfq_confirmed')
    elif 'state' in track_init_values and self.state == 'sent':
        return self.env.ref('purchase.mt_rfq_sent')
    return super()._track_log_get_default_subtype(track_init_values)

def action_receive(self):
    invalid_targets = self.filtered(
        lambda o: o.state != "purchase" or
        any(line.qty_received_method != "manual" for line in o.order_line)
    )
    if invalid_targets:
        raise UserError(
            _("The following purchase orders %(invalid_orders)s can't be received. Cancelled all receptions.",
            invalid_orders=invalid_targets))
    for order in self:
        for line in order.order_line:
            line.qty_received = line.product_qty

def button_approve(self, force=False):
    self = self.filtered(lambda order: order._approval_allowed())
    self.write({'state': 'purchase', 'date_approve': fields.Datetime.now()})
    self.filtered(lambda p: p.lock_confirmed_po == 'lock').write({'locked': True})
    return {}

def button_draft(self):
    self.write({'state': 'draft'})
    return {}

def button_confirm(self):
    for order in self:
        if order.state not in ['draft', 'sent']:
            continue
        error_msg = order._confirmation_error_message()
        if error_msg:
            raise UserError(error_msg)
        order.order_line._validate_analytic_distribution()
        # Deal with double validation process
        if order._approval_allowed():
            order.button_approve()
        else:
            order.write({'state': 'to approve'})
    return True

def button_cancel(self):
    locked_purchase_orders = self.filtered(lambda po: po.locked)
    if locked_purchase_orders:
        raise UserError(self.env._("Unable to cancel purchase order(s): %s. You must first unlock them.", locked_purchase_orders.mapped('display_name')))

    purchase_orders_with_invoices = self.filtered(lambda po: any(i.state not in ('cancel', 'draft') for i in po.invoice_ids))
    if purchase_orders_with_invoices:
        raise UserError(_("Unable to cancel purchase order(s): %s. You must first cancel their related vendor bills.", purchase_orders_with_invoices.mapped('display_name')))
    self.write({'state': 'cancel'})

def button_reset_date_order(self):
    self.ensure_one()
    previous_date_order = self.date_order
    self.date_order = fields.Datetime.now()
    for line in self.order_line:
        # If there's no seller i.e no lead time, we keep the same difference with the new deadline
        if not line.selected_seller_id and line.date_planned:
            diff = line.date_planned - previous_date_order
            line.date_planned = self.date_order + diff if diff.days >= 0 else self.date_order
        else:
            line.date_planned = line._get_date_planned(line.selected_seller_id._get_seller_info())

def _confirmation_error_message(self):
    """ Return whether order can be confirmed or not if not then return error message. """
    self.ensure_one()
    if any(
        not line.display_type
        and not line.is_downpayment
        and not line.product_id
        for line in self.order_line
    ):
        return _("Some order lines are missing a product, you need to correct them before going further.")

    return False

def action_bill_matching(self):
    self.ensure_one()
    return {
        'type': 'ir.actions.act_window',
        'name': _("Bill Matching"),
        'res_model': 'purchase.bill.line.match',
        'context': {
            'partner_id': self.partner_id.id,
        },
        'domain': [
            ('partner_id', 'in', (self.partner_id | self.partner_id.commercial_partner_id).ids),
            ('company_id', 'in', self.env.company.ids),
            '|', '|',
            ('purchase_order_id', '=', self.id),
            ('matching_id', '=', 0),
            ('aml_id.purchase_order_id', '=', self.id),
        ],
        'views': [(self.env.ref('purchase.purchase_bill_line_match_tree').id, 'list')],
    }

def _prepare_down_payment_section_values(self):
    self.ensure_one()
    context = {'lang': self.partner_id.lang}
    res = {
        'product_qty': 0.0,
        'order_id': self.id,
        'display_type': 'line_section',
        'is_downpayment': True,
        'sequence': (self.order_line[-1:].sequence or 9) + 1,
        'name': _("Down Payments"),
    }
    del context
    return res

def _create_downpayments(self, line_vals):
    self.ensure_one()

    # create section
    if not any(line.display_type and line.is_downpayment for line in self.order_line):
        section_line = self.order_line.create(self._prepare_down_payment_section_values())
    else:
        section_line = self.order_line.filtered(lambda line: line.display_type and line.is_downpayment)
    vals = [
        {
            **line_val,
            'sequence': section_line.sequence + i,
        }
        for i, line_val in enumerate(line_vals, start=1)
    ]
    downpayment_lines = self.env['purchase.order.line'].create(vals)
    self.order_line = [
        Command.link(line_id)
        for line_id in downpayment_lines.ids
    ]  # a simple concatenation would cause all order_line to recompute, we do not want it to happen
    return downpayment_lines

def action_view_invoice(self, invoices=False):
    """This function returns an action that display existing vendor bills of
    given purchase order ids. When only one found, show the vendor bill
    immediately.
    """
    if not invoices:
        self.invalidate_model(['invoice_ids'])
        invoices = self.invoice_ids

    result = self.env['ir.actions.act_window']._for_xml_id('account.action_move_in_invoice_type')
    # choose the view_mode accordingly
    if len(invoices) > 1:
        result['domain'] = [('id', 'in', invoices.ids)]
    elif len(invoices) == 1:
        res = self.env.ref('account.view_move_form', False)
        form_view = [(res and res.id or False, 'form')]
        if 'views' in result:
            result['views'] = form_view + [(state, view) for state, view in result['views'] if view != 'form']
        else:
            result['views'] = form_view
        result['res_id'] = invoices.id
    else:
        result = {'type': 'ir.actions.act_window_close'}

    result['context'] = literal_eval(result['context'])
    if len(self.partner_id) == 1:
        result['context']['default_partner_id'] = self.partner_id.id
    return result

def _send_reminder_mail(self, send_single=False):
    if not self.env.user.has_group('purchase.group_send_reminder'):
        return

    template = self.env.ref('purchase.email_template_edi_purchase_reminder', raise_if_not_found=False)
    if template:
        orders = self if send_single else self._get_orders_to_remind()
        for order in orders:
            date = order.date_planned
            if date and (send_single or (date - relativedelta(days=order.reminder_date_before_receipt)).date() == datetime.today().date()):
                if send_single:
                    return order._send_reminder_open_composer(template.id)
                else:
                    order.with_context(is_reminder=True).message_post_with_source(
                        template,
                        email_layout_xmlid="mail.mail_notification_layout_with_responsible_signature",
                        subtype_xmlid='mail.mt_comment',
                    )

