def _unlink_if_partner_in_purchase_order(self):
    """ Prevent the deletion of a partner if it is used in a PO dropship address"""

    po = self.sudo().env['purchase.order'].search_count([
        ('dest_address_id', 'in', self.ids),
        ('state', '!=', 'draft'),
    ])
    if po:
        raise UserError(_("The partner cannot be deleted because it is used as a dropship address"))

def credit_limit_amount(self):
    "Amount to check against credit limit"
    pool = Pool()
    Currency = pool.get('currency.currency')
    return Currency.compute(
        self.currency, self.untaxed_amount, self.company.currency)

def confirm(cls, sales):
    for sale in sales:
        if sale.must_check_credit_limit():
            party = sale.invoice_party or sale.party
            party.check_credit_limit(
                sale.credit_limit_amount, sale.company, origin=sale)
    super().confirm(sales)

def credit_limit_quantity(self):
    pool = Pool()
    UoM = pool.get('product.uom')
    if (self.type != 'line') or (self.quantity <= 0):
        return None
    quantity = self.quantity
    if self.sale.invoice_method == 'fulfillment':
        for move in self.moves_ignored:
            quantity -= UoM.compute_qty(
                move.unit, move.quantity, self.unit, round=False)
    for invoice_line in self.invoice_lines:
        if invoice_line.invoice in self.sale.invoices_ignored:
            quantity -= UoM.compute_qty(
                invoice_line.unit, invoice_line.quantity, self.unit,
                round=False)
    return quantity

def default_credit_limit_amount(cls, **pattern):
    pool = Pool()
    Configuration = pool.get('account.configuration')
    config = Configuration(1)
    return config.get_multivalue(
        'default_credit_limit_amount', **pattern)

